mapper.select:
SELECT c.id, c.customer_no, c.name, c.phone, c.email, COUNT(r.id) AS stay_count, c.created_at, c.updated_at FROM customers c LEFT JOIN reservations r ON r.customer_id = c.id
LOWER(c.name) LIKE LOWER(CONCAT('%', #{query}, '%')) OR c.customer_no LIKE CONCAT('%', #{query}, '%') OR COALESCE(c.phone, '') LIKE CONCAT('%', #{query}, '%') OR LOWER(COALESCE(c.email, '')) LIKE LOWER(CONCAT('%', #{query}, '%'))
GROUP BY c.id ORDER BY c.updated_at DESC, c.id DESC LIMIT #{limit}

SELECT c.id, c.customer_no, c.name, c.phone, c.email,
       COUNT(r.id) AS stay_count, c.created_at, c.updated_at
FROM customers c
LEFT JOIN reservations r ON r.customer_id = c.id
WHERE c.name = #{name}
  AND c.phone IS NOT DISTINCT FROM #{phone}
  AND c.email IS NOT DISTINCT FROM #{email}
GROUP BY c.id
ORDER BY c.id
LIMIT 1

mapper.update:
UPDATE customers
SET name=#{name}, phone=#{phone}, email=#{email}, updated_at=now()
WHERE id=#{id}
